%[text] # One Dimensional Advection Equation
%[text] THis is the report consistinbg my attempt of solving the advectiuon equatiuon in one dimension using this new **WENO Advection Scheme**. The scheme is fifth order, and due to some difficulty in the implementation of this algorithm, I found that the **Algorithm worked well for velocity that did not have any variation in space, but failed when velocity changed with space, in other words when the advection equation was non linear**. Now therefore to solve this problem I will implementing this algorithm in one dimension.
%[text] I was told that my implmentation might had some problem because when in two dimension there is possibility of making blunders in the indecies. However in one dimension, this may not happen, making it easier to debug the algorithm. 
%[text] So before starting the problem, given below is the problem description.
%[text] 
%[text] ## Problem Description (Grid Formation)
%[text] And here is the description of the grid used.
clc;
clear all;
%-------Domain Parameter-----%

% Grid Points
global Nx;
Nx = 400;

%--Important Parameters
INFINITE = 10^12;
global eta; eta = 10^-6;
error_eta = 10^-9;
CFL = 0.5;

% Dimension of Domain
Lx = 100;

% Domain
x = linspace(0,Lx,Nx);

% Defining velocity
global x_velocity;

% Space Interval
global h;
h = Lx/Nx;

% Total Time
t_total = 150;
%[text] ## Initial Condition
%[text] And this is the initial condition of the problem. As always, I have used Gaussian Initial Condition.
%[text] 
% Initial Condition (Density)

xc = 15;     % center x
sigma = 5;   % width
rho_gaussian = 0.2*exp(-((x-xc).^2) / (2*sigma^2) ) + 0.1;
%[text] ## Velocity Distribution
%[text] Here I have set the velocity distribution in the domain
%[text] 
% Initial Condition (Velocity)
%--Function to compute Velocity using Density
function speed = makeSpeed(rho)
    global Nx;
    speed = zeros(1,Nx);
    for i = 1:1:Nx
        speed(1,i) = 1 - rho(i);
    end
end

x_velocity = makeSpeed(rho_gaussian);
%[text] ## Plots
%[text] ### Initial Density
% Plot of Density
figure(1) %[output:76feddba]
plot(x,rho_gaussian,'*') %[output:76feddba]
title('Density (t = 0)') %[output:76feddba]
xlabel('x') %[output:76feddba]
ylabel('Density') %[output:76feddba]
xlim([0 100]) %[output:76feddba]
ylim([0 1]) %[output:76feddba]
axis square %[output:76feddba]
%[text] ### Initial Speed
% Plot of Density
figure(2) %[output:3c5b3ec9]
plot(x,x_velocity,'*') %[output:3c5b3ec9]
title('Velocity (t = 0)') %[output:3c5b3ec9]
xlabel('x') %[output:3c5b3ec9]
ylabel('Velocity') %[output:3c5b3ec9]
xlim([0 100]) %[output:3c5b3ec9]
ylim([0 1]) %[output:3c5b3ec9]
axis square; %[output:3c5b3ec9]
%[text] ### Flux Calculation
%-- Function that will calculate the flux depending on the u,v and Density.
function flux = makeFlux(rho)
    global Nx x_velocity;

    % Initialzing Flux
    flux = zeros(Nx);

    for i = 1:1:Nx
        flux(i) = rho(i) * x_velocity(i);
    end

    % Assign the boundary flux to be equal to zero
    flux(1) = 0;
end
%[text] ### Main Solver
rho = rho_gaussian %[output:67ba9c56]

%--Preallocating the memory
rho_n = zeros(Nx);
rho_1 = zeros(Nx);
rho_2 = zeros(Nx);
rho_next = zeros(Nx);


%-----------MAIN SOLVER------------%
t = 0; 
step = 0; % For plotting at regular interval

% Video
video = VideoWriter('One_Dimensional_Advection.avi','Motion JPEG AVI');
video.FrameRate = 20;
open(video);

while t< t_total %[output:group:325ef6d1]
    % Computing Cost For the density rho
    x_velocity = makeSpeed(rho);

    % Updating the delta_t with proper CFL condition (Wiki Pedia)
    u_max = max(x_velocity(:));
    dt = CFL / ( u_max/h + 1e-12 );

    % -- Making rho_n and RHS of rho_n
    rho_n = rho;
    semi_discritze_form_rho_n = makeRHS(rho_n);

    % ---------- Making the RHO_1 and then RHS of rho_1 ------ %
    for i = 4:1:Nx-2
        rho_1(i) = rho_n(i) + dt * semi_discritze_form_rho_n(i-3);
    end
    % -- Extrapolation (My Intuition)
    rho_1(3) = rho_1(4); rho_1(2) = rho_1(3); rho_1(1) = rho_1(2);  % Right Edge
    rho_1(Nx-1) = rho_1(Nx-2); rho_1(Nx) = rho_1(Nx-1);             % Left Edge
    % -- RHS of discritised form using rho_1
    semi_discritze_form_rho_1 = makeRHS(rho_1);


    %--------- Making the RHO_2 and RHS of RHO_2 ----------%
    for i = 4:1:Nx-2
        rho_2(i) = 3/4 * rho_n(i) + 1/4 * (rho_1(i) + dt * semi_discritze_form_rho_1(i-3));
    end
    % -- Extrapolation (My Intuition)
    rho_2(3) = rho_2(4); rho_2(2) = rho_2(3); rho_2(1) = rho_2(2);  % Right Edge
    rho_2(Nx-1) = rho_2(Nx-2); rho_2(Nx) = rho_2(Nx-1);             % Left Edge

    % -- RHS of discritised form using rho_2
    semi_discritze_form_rho_2 = makeRHS(rho_2);


    %----------Making the rho_next-------------------------%
    
    for i = 4:1:Nx-2
        rho_next(i) = 1/3 * rho_n(i) + 2/3 * (rho_2(i) + dt * semi_discritze_form_rho_2(i-3));
    end    
    % -- Extrapolation (My Intuition)
    rho_next(3) = rho_next(4); rho_next(2) = rho_next(3); rho_next(1) = rho_next(2);    % Right Edge
    rho_next(Nx-1) = rho_next(Nx-2); rho_next(Nx) = rho_next(Nx-1);                     % Left Edge

    step = step + 1;

    %--Plotting rho
    if mod(step,1) == 0
    
        figure(6); %[output:08e4bca7]
        plot(x, rho, '-');   % blue line with thickness %[output:08e4bca7]
        
        ylim([0 1]);
        xlim([0 100]);
        
        title(sprintf('Density at t = %.2f', t));
        xlabel('x');
        ylabel('\rho');
        
        grid on;
        axis square;
        
        drawnow;

        frame = getframe(gcf);
        writeVideo(video, frame);
    
    end


    % Substituting back the rho value \
    rho = rho_next;  

    % Updating the time
    t = t + dt;
end %[output:group:325ef6d1]
close(video);
%[text] ## One Dimensional Advection Solver using Lax Wendroff
%[text] Results of the one dimensional advectino equation using the fifth order weno scheme is shown above. Now I would like to solve this same problem using my old advectuino eyquation solver using **Lax Wendroff** scheme.
rho = rho_gaussian;
% This is the main time loop

% Reset the time and step
t = 0;
step = 0;

% Function for flux calculation
fF = @(rho) rho.*(1 - rho);

while t < t_total %[output:group:6368cc22]
    rho_old = rho;

    x_velocity = makeSpeed(rho);

    % Updating the delta_t with proper CFL condition (Wiki Pedia)
    u_max = max(x_velocity(:));
    dt = CFL / ( u_max/h + 1e-12 );

    for i = 2:Nx-1
        rho_half_right = 0.5*(rho_old(i)+rho_old(i+1)) - (dt/(2*h))*(fF(rho_old(i+1)) - fF(rho_old(i)));
        rho_half_left  = 0.5*(rho_old(i-1)+rho_old(i)) - (dt/(2*h))*(fF(rho_old(i)) - fF(rho_old(i-1)));

        F_half_right = rho_half_right.*(1 - rho_half_right);
        F_half_left  = rho_half_left.*(1 - rho_half_left);

        rho(i) = rho_old(i) - (dt/h)*(F_half_right - F_half_left);
    end
    
    % Boundary conditions
    rho(1) = 0; % i assign this dirichlet condition such that there is no inflow of people coming into the domain.
    rho(Nx) = rho(Nx-1); % Free boundary

    % Store snapshots every 'time_interval' steps
    %--Plotting rho
    if mod(step,5) == 0

        figure(7); %[output:7d9be5f7]
        plot(x, rho, '-');   % blue line with thickness %[output:7d9be5f7]
        
        ylim([0 1]);
        xlim([0 100]);
        
        title(sprintf('Density at t = %.2f', t));
        xlabel('x');
        ylabel('\rho');
        
        grid on;
        axis square;
        
        drawnow;

        frame = getframe(gcf);
    end

    step = step + 1;

     % Updating the time
    t = t + dt;
end %[output:group:6368cc22]
%[text] ### To find the expression for L(Rho)
function semi_discrete_form =  makeRHS(rho)
    global Nx x_velocity h;
    semi_discrete_form = zeros(Nx-5);

    %--Flux for the given rho distribution
    flux = makeFlux(rho);

    % Calculating the maximum speed
    alpha_x = max(x_velocity(:));


    % -- Calculating the value of f+ and f- at {i+2,i+1,i,i-1,i-2,i-3} -- %
    fx_negative_whole = zeros(Nx);
    fx_positive_whole = zeros(Nx);

    for i = 1:1:Nx
        fx_positive_whole(i) = 1/2 * (flux(i) + alpha_x*rho(i));
        fx_negative_whole(i) = 1/2 * (flux(i) - alpha_x*rho(i));
    end
    
    % -- Computing the RHS of Semi Discrite form.
    for i = 4:1:Nx-2
        %--X--%
        % fx{+}_[i+1/2,j]
        fx_plus_x_half_forward = stencil( ...
            fx_positive_whole(i-2), ...
            fx_positive_whole(i-1), ...
            fx_positive_whole(i), ...
            fx_positive_whole(i+1), ...
            fx_positive_whole(i+2));
            
        % fx{+}_[i-1/2,j]
        fx_plus_x_half_backward = stencil( ...
            fx_positive_whole(i-3), ...
            fx_positive_whole(i-2), ...
            fx_positive_whole(i-1), ...
            fx_positive_whole(i), ...
            fx_positive_whole(i+1));

        % fx{-}_[i+1/2,j]
        fx_minus_x_half_forward = stencil( ...
            fx_negative_whole(i+2), ...
            fx_negative_whole(i+1), ...
            fx_negative_whole(i), ...
            fx_negative_whole(i-1), ...
            fx_negative_whole(i-2));
            
        % fx{-}_[i-1/2,j]
        fx_minus_x_half_backward = stencil( ...
            fx_negative_whole(i+1), ...
            fx_negative_whole(i), ...
            fx_negative_whole(i-1), ...
            fx_negative_whole(i-2), ...
            fx_negative_whole(i-3));
            
        fx_positive_half = fx_plus_x_half_forward + fx_minus_x_half_forward;
        fx_negative_half = fx_plus_x_half_backward + fx_minus_x_half_backward;

        %--Boundary Condition -- %

        % Left Wall (Flux set to Zero)
        if(i == 4)
            fx_negative_half = 0;
            fx_positive_half = 0;
        end
        % Right Wall (Flux Set to Zero)
        if(i == Nx-2)
            fx_positive_half = fx_positive_half;
            fx_negative_half = fx_negative_half;
        end

        % Computing RHS of Semi Discritized form
        semi_discrete_form(i-3) = - 1/h * (fx_positive_half - fx_negative_half);    
    end
end

%[text] ## WENO Advection Stencil
% To compute f half. Order of input matters
function f = stencil(f1,f2,f3,f4,f5)
    global eta

    % Compute S values
    s_1 = ((1/3) * f1) + ((-7/6) * f2) + ((11/6) * f3);
    s_2 = ((-1/6) * f2) + ((5/6) * f3) + ((1/3) * f4);
    s_3 = ((1/3) * f3) + ((5/6) * f4) + ((-1/6) * f5);

    % Compute Beta
    beta_1 = 13/12 * (f1 - 2*f2 + f3)^2 + 1/4 * (f1 - 4*f2 + 3*f3)^2;
    beta_2 = 13/12 * (f2 - 2*f3 + f4)^2 + 1/4 * (f2 - f4)^2;
    beta_3 = 13/12 * (f3 - 2*f4 + f5)^2 + 1/4 * (3*f3 - 4*f4 + f5)^2;

    % Definign Gamma
    gamma_1 = 1/10;
    gamma_2 = 3/5;
    gamma_3 = 3/10;

    % Computing weights bar
    w_1_dash = ( gamma_1 ) ./ ((eta + beta_1)^2);
    w_2_dash = ( gamma_2 ) ./ ((eta + beta_2)^2);
    w_3_dash = ( gamma_3 ) ./ ((eta + beta_3)^2);

    % Computing Weights
    w_1 = ( w_1_dash ) / (w_1_dash + w_2_dash + w_3_dash);
    w_2 = ( w_2_dash ) / (w_1_dash + w_2_dash + w_3_dash);
    w_3 = ( w_3_dash ) / (w_1_dash + w_2_dash + w_3_dash);

    % Computing Flux
    f = w_1 * s_1 + w_2 * s_2 + w_3 * s_3;
end

